// define a function for generating plot data 

function get_data(x, alpha, beta) {
  var i;
  var points = [];

  for ( i = 0; i &lt; x.length; i++ ) {
        points.push({x: x[i], pdf_y: beta_pdf(x[i], alpha, beta), cdf_y: beta_cdf(x[i], alpha, beta)});
    }
    return points;
}










